const sample = `
<!doctype html><meta charset="utf-8">
<style>
@font-face { font-family: Cur; src: url(data:font/woff2;base64,${cur}) format('woff2'); font-weight: 300 900; }
@font-face { font-family: Ref; src: url(data:font/woff2;base64,${ref}) format('woff2'); font-weight: 300 900; }
body { margin: 0; background: #fff; }
.row { padding: 8px 16px; }
.label { font: 12px monospace; color: #999; }
.s { font-size: 34px; line-height: 1.3; white-space: nowrap; }
.cur { font-family: Cur; }
.ref { font-family: Ref; }
.w { font-size: 28px; margin: 2px 0; }
</style>
