<div class="w ref" style="font-weight:600">600 Small things — £12,400 · $49</div>
<div class="w ref" style="font-weight:800">800 Small things — £12,400 · $49</div>
<div class="w ref" style="font-weight:900">900 Small things — £12,400 · $49</div>
</div>`;
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1100, height: 900 }, deviceScaleFactor: 2 });
  await page.setContent(sample);
  await page.waitForTimeout(500);
  await page.screenshot({ path: process.env.TMPDIR + '/fontcompare.png', fullPage: true });
  const els = await page.locator('.row').all();
  await page.locator('.row').nth(0).screenshot({ path: process.env.TMPDIR + '/font-cur.png' });
  await page.locator('.row').nth(1).screenshot({ path: process.env.TMPDIR + '/font-ref.png' });
  await browser.close();
})();
