const sizes = [['desktop',1280,800],['phone',390,844]];
(async () => {
  const server = spawn(process.execPath, ['server.js'], { cwd: '/tmp/avb-lvzJXb/project', env: { ...process.env, PORT: String(port) }, stdio: 'ignore' });
  await new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error('server timeout')), 10000);
    server.stdout?.on('data', () => {});
    const tryFetch = async () => {
      try { const r = await fetch(base + '/'); if (r.ok) { clearTimeout(t); resolve(); return; } } catch {}
      setTimeout(tryFetch, 100);
    };
    tryFetch();
  });
  const browser = await chromium.launch();
  fs.mkdirSync(out, { recursive: true });
  for (const [proj,w,h] of sizes) {
    const ctx = await browser.newContext({ viewport: {width:w,height:h}, deviceScaleFactor: 1, colorScheme: 'light', locale: 'en-US', timezoneId: 'UTC', reducedMotion: 'no-preference' });
    const page = await ctx.newPage();
    for (const [name,url] of pages) {
      await page.goto(base + url, { waitUntil: 'load' });
      await page.evaluate(() => document.fonts.ready);
      await page.waitForTimeout(150);
      await page.screenshot({ path: path.join(out, `${name}__${proj}.png`), fullPage: true });
    }
    await ctx.close();
  }
  await browser.close();
  server.kill();
})();
